// Arduino Sketch
void setup() {
  pinMode(8, OUTPUT);
  pinMode(9, OUTPUT);
  pinMode(10, OUTPUT);
}

void loop() {
  digitalWrite(8, HIGH);
  delay(200);

  digitalWrite(9, HIGH);
  delay(200);

  digitalWrite(10, HIGH);
  delay(2000);

  digitalWrite(8, LOW);
  delay(200);

  digitalWrite(9, LOW);
  delay(200);

  digitalWrite(10, LOW);
  delay(2000);
}
